/* QR-КОД — кодировщик целиком в плагине: библиотек у потока нет, а QR нужен
   часто. Режим «байты» (UTF-8), версии 1–10 (до 274 байт), все четыре уровня
   стойкости. Выход — SVG, поэтому картинка на листе остаётся чёткой в любом
   масштабе.

   Разложено по шагам стандарта: биты → блоки → коды Рида — Соломона →
   чередование → матрица → маска. Сверено с эталонной библиотекой на наборе
   строк (Tests/pulsqr-test.js). */

/* по версии: [всего кодовых слов, [ЕС на блок, блоков1, данных1, блоков2, данных2] для L, M, Q, H] */
const QR_ТАБЛИЦА = [
  [26,  [7, 1, 19, 0, 0],   [10, 1, 16, 0, 0],  [13, 1, 13, 0, 0],  [17, 1, 9, 0, 0]],
  [44,  [10, 1, 34, 0, 0],  [16, 1, 28, 0, 0],  [22, 1, 22, 0, 0],  [28, 1, 16, 0, 0]],
  [70,  [15, 1, 55, 0, 0],  [26, 1, 44, 0, 0],  [18, 2, 17, 0, 0],  [22, 2, 13, 0, 0]],
  [100, [20, 1, 80, 0, 0],  [18, 2, 32, 0, 0],  [26, 2, 24, 0, 0],  [16, 4, 9, 0, 0]],
  [134, [26, 1, 108, 0, 0], [24, 2, 43, 0, 0],  [18, 2, 15, 2, 16], [22, 2, 11, 2, 12]],
  [172, [18, 2, 68, 0, 0],  [16, 4, 27, 0, 0],  [24, 4, 19, 0, 0],  [28, 4, 15, 0, 0]],
  [196, [20, 2, 78, 0, 0],  [18, 4, 31, 0, 0],  [18, 2, 14, 4, 15], [26, 4, 13, 1, 14]],
  [242, [24, 2, 97, 0, 0],  [22, 2, 38, 2, 39], [22, 4, 18, 2, 19], [26, 4, 14, 2, 15]],
  [292, [30, 2, 116, 0, 0], [22, 3, 36, 2, 37], [20, 4, 16, 4, 17], [24, 4, 12, 4, 13]],
  [346, [18, 2, 68, 2, 69], [26, 4, 43, 1, 44], [24, 6, 19, 2, 20], [28, 6, 15, 2, 16]],
];
const QR_ЦЕНТРЫ = [[], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34],
                   [6, 22, 38], [6, 24, 42], [6, 26, 46], [6, 28, 50]];
const QR_УРОВНИ = ['L', 'M', 'Q', 'H'];
const QR_ЕСБИТЫ = {L: 1, M: 0, Q: 3, H: 2};

/* поле Галуа GF(256) для кодов Рида — Соломона */
const QR_ЛОГ = new Uint8Array(256), QR_ЭКСП = new Uint8Array(512);
(function(){
  let x = 1;
  for(let i = 0; i < 255; i++){ QR_ЭКСП[i] = x; QR_ЛОГ[x] = i; x <<= 1; if(x & 0x100) x ^= 0x11D; }
  for(let i = 255; i < 512; i++) QR_ЭКСП[i] = QR_ЭКСП[i - 255];
})();
const qrУмн = (a, b) => (a && b) ? QR_ЭКСП[QR_ЛОГ[a] + QR_ЛОГ[b]] : 0;

function qrГенератор(n){
  let g = [1];
  for(let i = 0; i < n; i++){
    const с = new Array(g.length + 1).fill(0);
    for(let j = 0; j < g.length; j++){ с[j] ^= g[j]; с[j + 1] ^= qrУмн(g[j], QR_ЭКСП[i]); }
    g = с;
  }
  return g;
}
function qrКоды(данные, n){
  const g = qrГенератор(n), буф = данные.concat(new Array(n).fill(0));
  for(let i = 0; i < данные.length; i++){
    const к = буф[i]; if(!к) continue;
    for(let j = 0; j < g.length; j++) буф[i + j] ^= qrУмн(g[j], к);
  }
  return буф.slice(данные.length);
}
function qrUTF8(текст){
  const из = [];
  for(const з of String(текст)){
    const c = з.codePointAt(0);
    if(c < 0x80) из.push(c);
    else if(c < 0x800) из.push(0xC0 | (c >> 6), 0x80 | (c & 63));
    else if(c < 0x10000) из.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else из.push(0xF0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return из;
}
function qrФормат(уровень, маска){
  const д = (QR_ЕСБИТЫ[уровень] << 3) | маска;
  let r = д << 10;
  for(let i = 14; i >= 10; i--) if((r >> i) & 1) r ^= 0x537 << (i - 10);
  return ((д << 10) | (r & 0x3FF)) ^ 0x5412;
}
function qrВерсияБиты(в){
  let r = в << 12;
  for(let i = 17; i >= 12; i--) if((r >> i) & 1) r ^= 0x1F25 << (i - 12);
  return (в << 12) | (r & 0xFFF);
}
const QR_МАСКИ = [
  (i, j) => (i + j) % 2 === 0,
  (i, j) => i % 2 === 0,
  (i, j) => j % 3 === 0,
  (i, j) => (i + j) % 3 === 0,
  (i, j) => (Math.floor(i / 2) + Math.floor(j / 3)) % 2 === 0,
  (i, j) => ((i * j) % 2) + ((i * j) % 3) === 0,
  (i, j) => ((((i * j) % 2) + ((i * j) % 3)) % 2) === 0,
  (i, j) => ((((i + j) % 2) + ((i * j) % 3)) % 2) === 0,
];

/* Сколько байт вмещает уровень: самая большая версия минус заголовок
   (режим 4 бита + длина 16 бит у версии 10). */
function qrПредел(уровень){
  const у = QR_УРОВНИ.indexOf(уровень) >= 0 ? QR_УРОВНИ.indexOf(уровень) : 1;
  const [ес, б1, д1, б2, д2] = QR_ТАБЛИЦА[9][у + 1];
  return Math.floor(((б1 * д1 + б2 * д2) * 8 - 4 - 16) / 8);
}

/* Текст → матрица 0/1. Версия подбирается наименьшая, в которую влезает. */
function qrМатрица(текст, уровень){
  уровень = QR_УРОВНИ.indexOf(уровень) >= 0 ? уровень : 'M';
  const у = QR_УРОВНИ.indexOf(уровень);
  const байты = qrUTF8(текст);
  let версия = 0;
  for(let в = 1; в <= 10; в++){
    const [, ...ур] = QR_ТАБЛИЦА[в - 1];
    const [ес, б1, д1, б2, д2] = ур[у];
    const данных = б1 * д1 + б2 * д2;
    const счёт = в < 10 ? 8 : 16;
    if(данных * 8 >= 4 + счёт + байты.length * 8){ версия = в; break; }
  }
  if(!версия) throw new Error('Для QR это слишком длинно: ' + байты.length + ' байт при уровне '
    + уровень + '; предел — ' + qrПредел(уровень) + ' байт. Возьмите уровень пониже (L вмещает больше) '
    + 'или сократите текст.');

  const [ес, б1, д1, б2, д2] = QR_ТАБЛИЦА[версия - 1][у + 1];
  const данных = б1 * д1 + б2 * д2;

  /* биты: режим, длина, данные, конец, добивка */
  const биты = [];
  const класть = (з, сколько) => { for(let i = сколько - 1; i >= 0; i--) биты.push((з >> i) & 1); };
  класть(4, 4);
  класть(байты.length, версия < 10 ? 8 : 16);
  for(const b of байты) класть(b, 8);
  for(let i = 0; i < 4 && биты.length < данных * 8; i++) биты.push(0);
  while(биты.length % 8) биты.push(0);
  const слова = [];
  for(let i = 0; i < биты.length; i += 8){ let б = 0; for(let j = 0; j < 8; j++) б = (б << 1) | биты[i + j]; слова.push(б); }
  for(let i = 0; слова.length < данных; i++) слова.push(i % 2 ? 0x11 : 0xEC);

  /* блоки и коды исправления */
  let п = 0; const блоки = [], коды = [];
  for(const [сколько, длина] of [[б1, д1], [б2, д2]]) for(let i = 0; i < сколько; i++){
    const блок = слова.slice(п, п + длина); п += длина;
    блоки.push(блок); коды.push(qrКоды(блок, ес));
  }
  const поток = [];
  const самый = Math.max.apply(null, блоки.map(б => б.length));
  for(let i = 0; i < самый; i++) for(const б of блоки) if(i < б.length) поток.push(б[i]);
  for(let i = 0; i < ес; i++) for(const б of коды) поток.push(б[i]);

  /* матрица: сперва узоры, потом данные, потом маска */
  const n = версия * 4 + 17;
  const м = [], своё = [];
  for(let i = 0; i < n; i++){ м.push(new Array(n).fill(0)); своё.push(new Array(n).fill(false)); }
  const ставить = (r, c, в) => { if(r >= 0 && c >= 0 && r < n && c < n){ м[r][c] = в; своё[r][c] = true; } };

  const поиск = (r0, c0) => { for(let r = -1; r <= 7; r++) for(let c = -1; c <= 7; c++){
    const внутри = (r >= 0 && r <= 6 && (c === 0 || c === 6)) || (c >= 0 && c <= 6 && (r === 0 || r === 6))
      || (r >= 2 && r <= 4 && c >= 2 && c <= 4);
    ставить(r0 + r, c0 + c, внутри ? 1 : 0); } };
  поиск(0, 0); поиск(0, n - 7); поиск(n - 7, 0);
  for(let i = 8; i < n - 8; i++){ ставить(6, i, i % 2 === 0 ? 1 : 0); ставить(i, 6, i % 2 === 0 ? 1 : 0); }
  const центры = QR_ЦЕНТРЫ[версия - 1];
  for(const r of центры) for(const c of центры){
    if((r <= 8 && c <= 8) || (r <= 8 && c >= n - 9) || (r >= n - 9 && c <= 8)) continue;
    for(let dr = -2; dr <= 2; dr++) for(let dc = -2; dc <= 2; dc++)
      ставить(r + dr, c + dc, (Math.abs(dr) === 2 || Math.abs(dc) === 2 || (dr === 0 && dc === 0)) ? 1 : 0);
  }
  ставить(n - 8, 8, 1);
  for(let i = 0; i <= 8; i++){ ставить(8, i, м[8][i] || 0); ставить(i, 8, м[i][8] || 0); }
  for(let i = 0; i < 8; i++){ ставить(8, n - 1 - i, 0); ставить(n - 1 - i, 8, 0); }
  if(версия >= 7){
    const в = qrВерсияБиты(версия);
    for(let i = 0; i < 18; i++){ const б = (в >> i) & 1;
      ставить(Math.floor(i / 3), n - 11 + (i % 3), б);
      ставить(n - 11 + (i % 3), Math.floor(i / 3), б); }
  }
  let бит = 0, вверх = true;
  for(let c = n - 1; c > 0; c -= 2){
    if(c === 6) c--;
    for(let k = 0; k < n; k++){
      const r = вверх ? n - 1 - k : k;
      for(const cc of [c, c - 1]){
        if(своё[r][cc]) continue;
        м[r][cc] = бит < поток.length * 8 ? (поток[бит >> 3] >> (7 - (бит & 7))) & 1 : 0;
        бит++;
      }
    }
    вверх = !вверх;
  }

  /* маска: берём ту, у которой меньше штраф */
  let лучшая = 0, лучший = Infinity, итог = null;
  for(let маска = 0; маска < 8; маска++){
    const п2 = м.map((р, r) => р.map((з, c) => своё[r][c] ? з : (QR_МАСКИ[маска](r, c) ? з ^ 1 : з)));
    qrФорматВМатрицу(п2, n, уровень, маска);
    const ш = qrШтраф(п2, n);
    if(ш < лучший){ лучший = ш; лучшая = маска; итог = п2; }
  }
  return {матрица: итог, размер: n, версия: версия, уровень: уровень, маска: лучшая};
}

function qrФорматВМатрицу(м, n, уровень, маска){
  const ф = qrФормат(уровень, маска);
  /* старший бит формата ложится первым — в (8,0) и в нижний левый угол */
  for(let i = 0; i < 15; i++){
    const б = (ф >> (14 - i)) & 1;
    if(i < 6) м[8][i] = б;
    else if(i < 8) м[8][i + 1] = б;
    else if(i === 8) м[7][8] = б;
    else м[14 - i][8] = б;
    if(i < 7) м[n - 1 - i][8] = б;
    else м[8][n - 15 + i] = б;
  }
  м[n - 8][8] = 1;      /* всегда тёмный модуль — он не часть формата */
}

function qrШтраф(м, n){
  let ш = 0;
  /* подряд одинаковые */
  for(let i = 0; i < n; i++) for(const строкой of [true, false]){
    let было = -1, счёт = 0;
    for(let j = 0; j < n; j++){
      const з = строкой ? м[i][j] : м[j][i];
      if(з === было) счёт++; else { if(счёт >= 5) ш += счёт - 2; было = з; счёт = 1; }
    }
    if(счёт >= 5) ш += счёт - 2;
  }
  /* квадраты 2×2 */
  for(let r = 0; r < n - 1; r++) for(let c = 0; c < n - 1; c++)
    if(м[r][c] === м[r][c + 1] && м[r][c] === м[r + 1][c] && м[r][c] === м[r + 1][c + 1]) ш += 3;
  /* узор 10111010000 и обратный */
  const узор = [1, 0, 1, 1, 1, 0, 1, 0, 0, 0, 0];
  const сверить = (взять, от) => { for(let k = 0; k < 11; k++) if(взять(от + k) !== узор[k]) return false; return true; };
  const обратный = узор.slice().reverse();
  const сверитьО = (взять, от) => { for(let k = 0; k < 11; k++) if(взять(от + k) !== обратный[k]) return false; return true; };
  for(let i = 0; i < n; i++){
    const строка = j => (j < 0 || j >= n) ? -1 : м[i][j];
    const столб = j => (j < 0 || j >= n) ? -1 : м[j][i];
    for(let j = 0; j <= n - 11; j++){
      if(сверить(строка, j) || сверитьО(строка, j)) ш += 40;
      if(сверить(столб, j) || сверитьО(столб, j)) ш += 40;
    }
  }
  /* перекос тёмного и светлого */
  let тёмных = 0;
  for(let r = 0; r < n; r++) for(let c = 0; c < n; c++) тёмных += м[r][c];
  const доля = тёмных * 100 / (n * n);
  ш += Math.floor(Math.abs(доля - 50) / 5) * 10;
  return ш;
}

/* матрица → SVG: полосами, поэтому файл маленький */
function qrSVG(о, размер, цвет, фон, поля){
  const n = о.размер, всего = n + поля * 2;
  let d = '';
  for(let r = 0; r < n; r++){
    let c = 0;
    while(c < n){
      if(!о.матрица[r][c]){ c++; continue; }
      let к = c; while(к < n && о.матрица[r][к]) к++;
      d += 'M' + (c + поля) + ' ' + (r + поля) + 'h' + (к - c) + 'v1h-' + (к - c) + 'z';
      c = к;
    }
  }
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + всего + ' ' + всего
    + '" width="' + размер + '" height="' + размер + '">'
    + '<rect width="' + всего + '" height="' + всего + '" fill="' + фон + '"/>'
    + '<path d="' + d + '" fill="' + цвет + '"/></svg>';
}

/* --- плагин ---------------------------------------------------------------- */

const ПРЕДЕЛ = {L: qrПредел('L'), M: qrПредел('M'), Q: qrПредел('Q'), H: qrПредел('H')};

function текстДляКода(п){
  if(п.откуда === 'из клетки'){
    const в = книга.выделение, з = ячейка(в.адрес).значение;
    return з === null || з === undefined ? '' : String(з);
  }
  return String(п.текст || '');
}

function нарисовать(текст, п){
  const о = qrМатрица(текст, п.уровень || 'M');
  const бок = Math.max(32, Math.min(600, +п.размер || 160));
  return {свг: qrSVG(о, бок, п.цвет || '#000000', п.фон || '#ffffff',
                     Math.max(0, Math.min(8, +п.поля === 0 ? 0 : (+п.поля || 4)))), о: о, бок: бок};
}

function Вставить(){
  const п = параметры({}), текст = текстДляКода(п);
  if(!текст){ панель.сообщение('Нечего кодировать: введите текст или встаньте на клетку со значением'); return; }
  let р; try { р = нарисовать(текст, п); } catch(e){ панель.сообщение(e.message); return; }
  const в = книга.выделение;
  картинка.вставить(р.свг, {адрес: в.адрес, ширина: р.бок, высота: р.бок, имя: 'QR: ' + текст.slice(0, 40)});
  панель.сообщение('QR на ' + в.адрес + ': версия ' + р.о.версия + ', уровень ' + р.о.уровень
    + ', сторона ' + р.о.размер + ' модулей');
}

/* Объект плагина: при нём остаются свои данные, поэтому его можно править
   двойным щелчком — плагин поднимется сам и покажет, что было закодировано. */
function Объектом(){
  const п = параметры({}), текст = текстДляКода(п);
  if(!текст){ панель.сообщение('Нечего кодировать'); return; }
  let р; try { р = нарисовать(текст, п); } catch(e){ панель.сообщение(e.message); return; }
  const в = книга.выделение;
  const свои = {текст: текст, уровень: п.уровень || 'M', размер: р.бок, цвет: п.цвет || '#000000',
                фон: п.фон || '#ffffff', поля: +п.поля === 0 ? 0 : (+п.поля || 4)};
  картинка.объект(р.свг, свои, {адрес: в.адрес, ширина: р.бок, высота: р.бок, имя: 'QR: ' + текст.slice(0, 40)});
  панель.сообщение('QR-объект на ' + в.адрес + ' — двойной щелчок по нему откроет правку');
}

/* Двойной щелчок по объекту: показываем, что в нём, и даём переписать */
async function Править(){
  const п = книга.повод;
  let свои = {};
  try { свои = JSON.parse(п.свои || '{}'); } catch(e){}
  const новый = await диалог.ввод('Что закодировать?', свои.текст || '');
  if(новый === null) return;
  const было = {уровень: свои.уровень || 'M', размер: свои.размер || 160, цвет: свои.цвет || '#000000',
                фон: свои.фон || '#ffffff', поля: свои.поля === 0 ? 0 : (свои.поля || 4)};
  let р; try { р = нарисовать(новый, было); } catch(e){ await диалог.сообщение(e.message); return; }
  картинка.изменить(п.id, {данные: р.свг, свои: Object.assign({}, было, {текст: новый}),
                           имя: 'QR: ' + новый.slice(0, 40)});
}

/* Пункт меню на любой клетке: QR прямо из её значения */
function ИзКлетки(){
  const п = книга.повод, н = параметры({});
  const текст = п.значение === null || п.значение === undefined ? '' : String(п.значение);
  if(!текст) return;
  let р; try { р = нарисовать(текст, н); } catch(e){ return; }
  картинка.вставить(р.свг, {адрес: п.адрес, ширина: р.бок, высота: р.бок, имя: 'QR: ' + текст.slice(0, 40)});
}

/* Столбец значений → столбец QR рядом. Строкам с кодами — высота под код,
   столбцу кодов — ширина, с полем в две точки вокруг: прежде код 160×160
   ложился на строку в 24 точки, наползал на соседние, и весь столбец выглядел
   одной стопкой в одной клетке. Строку или столбец, что уже выше или шире
   нужного, не сжимаем. */
const QR_ПОЛЕ = 2;                                   // точек от края клетки до кода
async function Столбцом(){
  const п = параметры({}), в = книга.выделение;
  const строки = await лист(в.лист).прочитать(в.область);
  const листApi = Api.GetSheet(в.лист);
  let сделано = 0, бок = 0;
  for(let i = 0; i < строки.length; i++){
    const з = строки[i][0];
    if(з === null || з === undefined || з === '') continue;
    let р; try { р = нарисовать(String(з), п); } catch(e){ continue; }
    картинка.вставить(р.свг, {строка: в.r1 + i, столбец: в.c2 + 1, сдвигX: QR_ПОЛЕ, сдвигY: QR_ПОЛЕ,
                              ширина: р.бок, высота: р.бок, имя: 'QR: ' + String(з).slice(0, 40)});
    /* высота строки — в пунктах: точки × 0,75 */
    const клетка = листApi.GetRangeByNumber(в.r1 + i - 1, в.c2), пунктов = (р.бок + 2 * QR_ПОЛЕ) * 0.75;
    if(клетка.GetRowHeight() < пунктов) клетка.SetRowHeight(пунктов);
    бок = Math.max(бок, р.бок);
    сделано++;
    if(сделано >= 200) break;
  }
  /* ширина столбца — в знаках: точки ÷ 7 */
  if(сделано){
    const столбец = листApi.GetRangeByNumber(в.r1 - 1, в.c2), знаков = (бок + 2 * QR_ПОЛЕ) / 7;
    if(столбец.GetColumnWidth() < знаков) столбец.SetColumnWidth(знаков);
  }
  панель.сообщение('Кодов поставлено: ' + сделано + (сделано >= 200 ? ' (больше 200 за раз не делаем)' : ''));
}

function Проверить(){
  const п = параметры({}), текст = текстДляКода(п);
  if(!текст){ панель.поле('сведения', 'нечего кодировать'); return; }
  const байт = qrUTF8(текст).length;
  let о = null; try { о = qrМатрица(текст, п.уровень || 'M'); } catch(e){ панель.поле('сведения', e.message); return; }
  панель.поле('сведения', байт + ' байт, версия ' + о.версия + ', сторона ' + о.размер
    + ' модулей, предел уровня ' + (п.уровень || 'M') + ' — ' + ПРЕДЕЛ[п.уровень || 'M'] + ' байт');
}
